import{z as A,x as s,o as e,c as d,q as r,j as i,D as E,d as t,s as o,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"做市商义务与撤退","description":"","frontmatter":{"title":"做市商义务与撤退","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-obligations-withdrawal.md","filePath":"quant/mm-obligations-withdrawal.md","lastUpdated":1791063341000}'),p={name:"quant/mm-obligations-withdrawal.md"};function m(C,a,u,h,c,D){const B=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="做市商义务与撤退" tabindex="-1">做市商义务与撤退 <a class="header-anchor" href="#做市商义务与撤退" aria-label="Permalink to &quot;做市商义务与撤退&quot;">​</a></h1><div class="epigraph"><p>平静期自愿在场的做市商，在方差或库存越限时会关掉算法。义务条款试图把 Grossman–Miller 的 $M$ 在压力期钉住，但钉得太死会让人事先不愿进入，钉得太松则闪崩路径仍在。</p><footer>—— 据 Grossman and Miller, Liquidity and Market Structure, Journal of Finance, 1988；经验上做市商资本与撤退见 Anand and Venkataraman, Market conditions, fragility, and the economics of market making, Journal of Financial Economics, 2016</footer></div><p><a href="/quant/spoofing-layering">幌骚</a>是伪造供给。缺口是真实供给的<strong>选择性在场</strong>：高频做市没有传统专家那种硬义务时，Ho–Stoll 的限额变成撤退开关。Anand 与 Venkataraman（2016）讨论做市脆弱性；交易所指定做市商（DMM）、NASDAQ 做市商、期权指定商仍带有报价义务。本课写义务与撤退的权衡，接闪电崩盘的供给弹性，不写某司法辖区的条文清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自愿做市的进入条件是：平静期价差收入覆盖资本与被捡。压力期被捡与库存方差跳升，自愿最优是 \\(\\tau\\to 0\\) 直至离场。社会最优可能希望他们留下，因为即时性的外部性（别人的止损、价格作为公共信号）未被价差完全内部化。义务把留下写成约束：最大价差、最小深度、最短在场时间。问题是校准：义务过严，进入的 \\(M\\) 下降或要求更高的平时价差补贴；义务过松，约束在闪崩时恰好不绑定。</p><p><span class="marginnote">术语翻译：做市义务就是交易所与做市商签的「值班合同」——平时给你手续费减免、数据优惠、拍卖参与权等特权，换你承诺价差不超过上限、每侧至少挂多少量、在场时间达标；不达标就取消特权或资格。特权换在场，是这一课的全部机制。</span></p><p>指定做市商常用特权（费用、信息、拍卖参与）交换义务。这是把 Ho–Stoll 的垄断租金部分退回，换压力期在场——Seppi 意义上专家与限价簿并存的制度版本。</p><h3 id="撤退是风控-不是一定是恶意" tabindex="-1">撤退是风控，不是一定是恶意 <a class="header-anchor" href="#撤退是风控-不是一定是恶意" aria-label="Permalink to &quot;撤退是风控，不是一定是恶意&quot;">​</a></h3><p>库存模型里硬约束使报价不连续：达到限额即单边或双边撤空。看起来像「扔下市场」，对个体是有限资本的最优。政策若惩罚撤退本身，等于要求无限资本，进入会少。更好的设计是熔断给补给时间、或中央对手方降低尾部，而不是假装 \\(M\\) 可以无限。</p><p><span class="marginnote">欧盟与美国对做市义务的写法不同，期权、期货、股票又不同。本课只保留「特权换在场」的机制，不比较法条。</span></p><p><span class="marginnote">数字实例：一份典型义务长这样——报价价差不超过 0.5%、每侧至少挂 200 手、每月在场时间不低于 85%。库存模型的限额一旦触发，算法就单边或双边撤空；于是「义务参数 + 风控限额」共同决定压力期簿上还剩什么：义务定的是外部承诺，限额定的是内部开关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>经验：识别指定做市商账户，比较义务股票与对照股票在压力窗的价差、深度、撤退概率。Anand–Venkataraman 强调资本与市场条件。事件：波动率跳升、相关市场中断、个股跳水。结果模式：自愿 HFT 深度比义务做市商更快消失；义务做市商在上限内加宽，但仍可能达到义务允许的最宽价差。</p><p>理论：Grossman–Miller 的进入均衡加一个「压力期必须在场」的约束，进入成本上升，平静期 \\(M\\) 可能下降。净福利取决于压力期外部性有多大——闪崩式分配损失 vs 平时更宽的价差。</p>',14)),(e(),i(l,null,{default:E(()=>[o(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20Calm%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%E8%87%AA%E6%84%BF%E5%9C%A8%E5%9C%BA%22%5D%20--%3E%20Stress%5B%22%E6%96%B9%E5%B7%AE%20%2F%20%E5%BA%93%E5%AD%98%E8%B6%8A%E9%99%90%22%5D%0A%20%20Stress%20--%3E%20Exit%5B%22%E7%AE%97%E6%B3%95%E5%85%B3%E9%97%AD%22%5D%0A%20%20Obl%5B%22%E6%8A%A5%E4%BB%B7%E4%B9%89%E5%8A%A1%20%2B%20%E7%89%B9%E6%9D%83%22%5D%20--%3E%20Stay%5B%22%E5%8E%8B%E5%8A%9B%E6%9C%9F%E4%BB%8D%E6%8A%A5%E4%BD%86%E6%9B%B4%E5%AE%BD%22%5D%0A%20%20Exit%20--%3E%20Gap%5B%22%E7%A9%BA%E7%B0%BF%E8%B7%AF%E5%BE%84%22%5D%0A%20%20Stay%20--%3E%20Cost%5B%22%E8%BF%9B%E5%85%A5%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"义务把暂时折让的上界切开：价格不能完全沿空簿走，除非义务也被击穿或触发停牌。这与涨跌停、LULD 是同类的硬边界，只是实施者是做市商而不是引擎。代价是做市商在义务区间内承担更大库存，要求事先补偿，价差的处理与库存成分上升。信息成分不会因为义务消失：被捡仍在，义务商可能用更短寿命在允许范围内闪烁。",-1)),a[5]||(a[5]=n("p",null,"跨市场：一处有义务、相关处没有，压力会转到无义务场所先崩，再通过套利拖垮有义务的场所。义务必须认清领先市场在哪。",-1)),(e(),i(l,null,{default:E(()=>[o(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E5%86%B2%E5%87%BB%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20NOBL%5B%22%E6%97%A0%E4%B9%89%E5%8A%A1%E5%9C%BA%E6%89%80%EF%BC%9AHFT%20%E6%92%A4%E9%80%80%EF%BC%8C%E6%B7%B1%E5%BA%A6%E5%85%88%E6%B6%88%E5%A4%B1%22%5D%0A%20%20NOBL%20--%3E%20PRICE%5B%22%E8%AF%A5%E5%9C%BA%E6%89%80%E4%BB%B7%E6%A0%BC%E5%85%88%E5%B4%A9%22%5D%0A%20%20PRICE%20--%3E%20ARB%5B%22%E5%A5%97%E5%88%A9%E6%8A%8A%E5%8E%8B%E5%8A%9B%E6%8B%96%E5%90%91%E6%9C%89%E4%B9%89%E5%8A%A1%E5%9C%BA%E6%89%80%22%5D%0A%20%20ARB%20--%3E%20OBL%5B%22%E4%B9%89%E5%8A%A1%E5%81%9A%E5%B8%82%E5%95%86%E8%A2%AB%E8%BF%AB%E6%8E%A5%E5%BA%93%E5%AD%98%E6%88%96%E8%BE%BE%E5%88%B0%E4%B9%89%E5%8A%A1%E4%B8%8A%E7%95%8C%22%5D%0A%20%20OBL%20--%3E%20EITHER%7B%22%E4%B9%89%E5%8A%A1%E4%B8%8E%E8%B5%84%E6%9C%AC%E5%A4%9F%E5%8E%9A%EF%BC%9F%22%7D%0A%20%20EITHER%20--%3E%7C%22%E6%98%AF%22%7C%20HELD%5B%22%E4%BB%B7%E6%A0%BC%E8%A2%AB%E4%B9%89%E5%8A%A1%E5%8C%BA%E9%97%B4%E6%89%98%E4%BD%8F%22%5D%0A%20%20EITHER%20--%3E%7C%22%E5%90%A6%22%7C%20CRACK%5B%22%E4%B9%89%E5%8A%A1%E5%87%BB%E7%A9%BF%EF%BC%8C%E8%BF%9E%E9%94%81%E4%B8%8B%E8%B7%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>义务不能创造资本。2010 年类事件里，若亏损超过资本，义务只是加快谁先破产。中央清算、保证金、熔断是配套。把「恢复专家垄断」当成解决 HFT 撤退的方案，会忽略电子簿在平静期的价差收益。混合设计（义务 + 自愿 HFT）是现实，纯模型两端都不存在。</p><p><span class="marginnote">常见误区：以为「有义务做市商在，闪崩就不会发生」。义务只是把暂时折让的上界切开；冲击一旦超过义务商的资本、或义务上界本身被击穿，价格照样走空簿路径。义务买的是温和情形下的托底，不是极端情形的保险——所以熔断与中央清算是必要配套，不是重复建设。</span></p><p><span class="marginnote">考核做市商用「平时报价时长」会选出平静期挂机、压力期掉线的人。考核应加权尾部在场，尽管更难测量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自愿高频做市在压力期理性撤退；义务用特权换有界在场，但提高进入成本。</li><li>撤退是有限资本的库存约束，闪崩路径是加总结果。</li><li>跨市场义务不对称会把压力转移到领先的无义务场所。</li><li>出处：Grossman and Miller, <em>Journal of Finance</em>, 1988；Anand and Venkataraman, <em>Journal of Financial Economics</em>, 2016。</li></ul>',6))])}const _=A(p,[["render",m]]);export{F as __pageData,_ as default};
